00046 // Extract the single-bit-per-transform signalling as a mask
00047 //
00048 Surface TemporalExtractMask::process(const Surface &symbols) {
00049     const auto src_symbols = symbols.view_as<int16_t>();
00050 
00051 #if defined __OPT_MATRIX__
00052     auto dest = Surface::build_from<uint8_t>();
00053     dest.reserve(src_symbols.width(), src_symbols.height());
00054     for (unsigned y = 0; y < src_symbols.height(); ++y) {
00055         const int16_t *__restrict psrc = src_symbols.data(0, y);
00056         uint8_t *__restrict pdst = dest.data(0, y);
00057         for (unsigned x = 0; x < src_symbols.width(); ++x) {
00058             // dest.write(x, y, (src_symbols.read(x, y) & 1) ? TemporalType::TEMPORAL_INTR : TemporalType::TEMPORAL_PRED);
00059             *pdst++ = ((*psrc++ & 1) ? TemporalType::TEMPORAL_INTR : TemporalType::TEMPORAL_PRED);
00060         }
00061     }
00062     return dest.finish();
00063 #else
00064     return Surface::build_from<uint8_t>()
00065         .generate(src_symbols.width(), src_symbols.height(),
00066                   [&](unsigned x, unsigned y) -> uint8_t {
00067                       return (src_symbols.read(x, y) & 1) ? TemporalType::TEMPORAL_INTR : TemporalType::TEMPORAL_PRED;
00068                   })
00069         .finish();
00070 #endif
00071 }
00072 
00073 // Filter out the single-bit-per-transform signalling as a mask
00074 //
00075 Surface TemporalClear::process(const Surface &symbols) {
00076     const auto src_symbols = symbols.view_as<int16_t>();
00077 
00078 #if defined __OPT_MATRIX__
00079     auto dest = Surface::build_from<int16_t>();
00080     dest.reserve(src_symbols.width(), src_symbols.height());
00081     for (unsigned y = 0; y < src_symbols.height(); ++y) {
00082         const int16_t *__restrict psrc = src_symbols.data(0, y);
00083         int16_t *__restrict pdst = dest.data(0, y);
00084         for (unsigned x = 0; x < src_symbols.width(); ++x) {
00085             // dest.write(x, y, (src_symbols.read(x, y) >> 1));
00086             *pdst++ = (*psrc++ >> 1);
00087         }
00088     }
00089     return dest.finish();
00090 #else
00091     return Surface::build_from<int16_t>()
00092         .generate(src_symbols.width(), src_symbols.height(),
00093                   [&](unsigned x, unsigned y) -> int16_t { return src_symbols.read(x, y) >> 1; })
00094         .finish();
00095 #endif
00096 }
00097 
00098 // Combine the previous temporal buffer, the current residuals and the signalling mask to make a new temporal buffer
00099 //
00100 Surface TemporalUpdate::process(const Surface &temporal_plane, const Surface &residuals_plane, Surface &mask_plane,
00101                                 unsigned transform_block_size, bool per_picture_intra, bool use_reduced_signalling) {
00102     if (mask_plane.empty()) {
00103         mask_plane = Surface::build_from<uint8_t>()
00104                          .generate(residuals_plane.width() / transform_block_size, residuals_plane.height() / transform_block_size,
00105                                    [&](unsigned x, unsigned y) -> uint8_t { return TemporalType::TEMPORAL_INTR; })
00106                          .finish();
00107     }
00108     const auto src_temporal = temporal_plane.view_as<int16_t>();
00109     const auto src_residuals = residuals_plane.view_as<int16_t>();
00110     const auto src_mask = mask_plane.view_as<uint8_t>();
00111 
00112     const unsigned tb_shift = log2(transform_block_size);
00113     const unsigned d = 32 / transform_block_size;
00114 
00115 #if defined __OPT_MATRIX__
00116     auto dest = Surface::build_from<int16_t>();
00117     dest.reserve(src_temporal.width(), src_temporal.height());
00118     for (unsigned y = 0; y < src_temporal.height(); ++y) {
00119         const int16_t *__restrict psrc = src_residuals.data(0, y);
00120         int16_t *__restrict pdst = dest.data(0, y);
00121         for (unsigned x = 0; x < src_temporal.width(); ++x) {
00122             const bool per_tile_intra =
00123                 use_reduced_signalling && (src_mask.read((x >> 5) * d, (y >> 5) * d) == TemporalType::TEMPORAL_INTR);
00124             const bool per_block_intra = (src_mask.read(x >> tb_shift, y >> tb_shift) == TemporalType::TEMPORAL_INTR);
00125             // int16_t out = 0;
00126             if (per_picture_intra || per_tile_intra || per_block_intra) {
00127                 // out = src_residuals.read(x, y);
00128                 *pdst++ = *psrc++;
00129             } else {
00130                 // out = src_residuals.read(x, y) + src_temporal.read(x, y);
00131                 *pdst++ = *psrc++ + src_temporal.read(x, y);
00132             }
00133             // dest.write(x, y, out);
00134         }
00135     }
00136     return dest.finish();
00137 #else
00138     return Surface::build_from<int16_t>()
00139         .generate(src_temporal.width(), src_temporal.height(),
00140                   [&](unsigned x, unsigned y) -> int16_t {
00141                       const bool per_tile_intra =
00142 #if defined __OPT_DIVISION__
00143                           use_reduced_signalling && (src_mask.read((x >> 5) * d, (y >> 5) * d) == TemporalType::TEMPORAL_INTR);
00144 #else
00145                           use_reduced_signalling && (src_mask.read((x / 32) * d, (y / 32) * d) == TemporalType::TEMPORAL_INTR);
00146 #endif
00147                       const bool per_block_intra = (src_mask.read(x >> tb_shift, y >> tb_shift) == TemporalType::TEMPORAL_INTR);
00148 
00149                       if (per_picture_intra || per_tile_intra || per_block_intra) {
00150                           return src_residuals.read(x, y);
00151                       } else {
00152                           return src_residuals.read(x, y) + src_temporal.read(x, y);
00153                       }
00154                   })
00155         .finish();
00156 #endif
00157 }
