00159 // Perform a per-tile temporal decision based upon the calculated residuals
00160 // for each pass and store result in a tile-map.
00161 //
00162 
00163 const std::vector<SurfaceView<int16_t>> TemporalTileMap::collect_surfaces_DD(Surface symbols[MAX_NUM_LAYERS]) {
00164     using view_t = SurfaceView<int16_t>;
00165     const std::vector<view_t> surfaces = {view_t{symbols[0]}, view_t{symbols[1]}, view_t{symbols[2]}, view_t{symbols[3]}};
00166     return surfaces;
00167 }
00168 
00169 const std::vector<SurfaceView<int16_t>> TemporalTileMap::collect_surfaces_DDS(Surface symbols[MAX_NUM_LAYERS]) {
00170     using view_t = SurfaceView<int16_t>;
00171     const std::vector<view_t> surfaces = {view_t{symbols[0]},  view_t{symbols[1]},  view_t{symbols[2]},  view_t{symbols[3]},
00172                                           view_t{symbols[4]},  view_t{symbols[5]},  view_t{symbols[6]},  view_t{symbols[7]},
00173                                           view_t{symbols[8]},  view_t{symbols[9]},  view_t{symbols[10]}, view_t{symbols[11]},
00174                                           view_t{symbols[12]}, view_t{symbols[13]}, view_t{symbols[14]}, view_t{symbols[15]}};
00175     return surfaces;
00176 }
00177 
00178 Surface TemporalTileMap::process(Surface intra_symbols[MAX_NUM_LAYERS], Surface inter_symbols[MAX_NUM_LAYERS],
00179                                  unsigned transform_block_size) {
00180     const unsigned tile_size = 32;
00181     const unsigned transforms_per_tile = tile_size / transform_block_size;
00182 
00183     const unsigned level_width = intra_symbols[0].width() * transform_block_size;
00184     const unsigned level_height = intra_symbols[0].height() * transform_block_size;
00185 
00186     const unsigned tiles_wide = (level_width + tile_size - 1) / tile_size;
00187     const unsigned tiles_high = (level_height + tile_size - 1) / tile_size;
00188 
00189     // These all have S=2 as template param in inverse.
00190     const std::vector<SurfaceView<int16_t>> srcs_intra =
00191         (transform_block_size == 2) ? collect_surfaces_DD(intra_symbols) : collect_surfaces_DDS(intra_symbols);
00192 
00193     const std::vector<SurfaceView<int16_t>> srcs_inter =
00194         (transform_block_size == 2) ? collect_surfaces_DD(inter_symbols) : collect_surfaces_DDS(inter_symbols);
00195 
00196     return Surface::build_from<uint8_t>()
00197         .generate(tiles_wide, tiles_high,
00198                   [&](unsigned x, unsigned y) -> uint8_t {
00199                       // This can be based on 2x2 regions, even for DDS.
00200                       unsigned both_z = 0;
00201                       unsigned inter_nz = 0;
00202                       unsigned inter_z = 0;
00203                       unsigned intra_nz = 0;
00204                       unsigned intra_z = 0;
00205                       unsigned inter_accum = 0;
00206                       unsigned intra_accum = 0;
00207                       unsigned sav_mixed = 0;
00208 
00209                       for (unsigned tile_y = y * transforms_per_tile; tile_y < (y + 1) * transforms_per_tile; ++tile_y) {
00210                           if (tile_y >= intra_symbols[0].height())
00211                               continue;
00212 
00213                           for (unsigned tile_x = x * transforms_per_tile; tile_x < (x + 1) * transforms_per_tile; ++tile_x) {
00214                               if (tile_x >= intra_symbols[0].width())
00215                                   continue;
00216 
00217                               // for each transform in each tile.
00218                               unsigned intra_sav = 0;
00219                               unsigned inter_sav = 0;
00220 
00221                               for (unsigned l = 0; l < transform_block_size * transform_block_size; ++l) {
00222                                   intra_sav += std::abs(srcs_intra[l].read(tile_x, tile_y));
00223                                   inter_sav += std::abs(srcs_inter[l].read(tile_x, tile_y));
00224                               }
00225 
00226                               if (inter_sav == 0 && intra_sav == 0) {
00227                                   both_z++;
00228                               } else if (inter_sav == 0) {
00229                                   inter_z++;
00230                               } else if (intra_sav == 0) {
00231                                   intra_z++;
00232                               } else if (intra_sav < inter_sav) {
00233                                   intra_nz++;
00234                               } else {
00235                                   inter_nz++;
00236                               }
00237 
00238                               intra_accum += intra_sav;
00239                               inter_accum += inter_sav;
00240                               // sav_mixed += std::min(intra_sav, inter_sav);
00241                               sav_mixed += LCEVC_MIN(intra_sav, inter_sav);
00242                           }
00243                       }
00244 
00245                       unsigned num_temporals = intra_z + intra_nz + inter_z + inter_nz;
00246                       unsigned intra_pct = (100 * (intra_z + intra_nz)) / (num_temporals + 1);
00247                       unsigned inter_pct = (100 * inter_z) / (num_temporals + 1);
00248 
00249                       unsigned intra_accum_75 = intra_accum - (inter_accum >> 2);
00250                       unsigned inter_accum_25 = inter_accum >> 2;
00251 
00252                       if (intra_pct > 38 && inter_pct < 20 && (intra_accum_75 <= sav_mixed || inter_accum_25 > sav_mixed)) {
00253                           return TemporalType::TEMPORAL_INTR;
00254                       }
00255 
00256                       return TemporalType::TEMPORAL_PRED;
00257                   })
00258         .finish();
00259 }
00260 
00261 // Perform sweep updating temporal mask based upon tile type with reduced signalling.
00262 //
00263 Surface TemporalTileIntraSignal::process(const Surface &temporal_tile_map, const Surface &mask_plane,
00264                                          unsigned transform_block_size) {
00265     const unsigned transforms_per_tile = 32 / transform_block_size;
00266     const auto src_tile_map = temporal_tile_map.view_as<uint8_t>();
00267     const auto src_mask_plane = mask_plane.view_as<uint8_t>();
00268 
00269     return Surface::build_from<uint8_t>()
00270         .generate(mask_plane.width(), mask_plane.height(),
00271                   [&](unsigned x, unsigned y) -> uint8_t {
00272                       const unsigned tile_x = x / transforms_per_tile;
00273                       const unsigned tile_y = y / transforms_per_tile;
00274 
00275                       const bool tile_intra = (src_tile_map.read(tile_x, tile_y) == TemporalType::TEMPORAL_INTR);
00276                       const bool tile_start = ((x % transforms_per_tile) == 0) && ((y % transforms_per_tile) == 0);
00277 
00278                       if (tile_intra)
00279                           return TemporalType::TEMPORAL_INTR;
00280                       else if (tile_start)
00281                           return TemporalType::TEMPORAL_PRED;
00282 
00283                       // Pass through the mask based on cost
00284                       return src_mask_plane.read(x, y);
00285                   })
00286         .finish();
00287 }
