00289 // Clear out the symbols where the temporal tile type is intra.
00290 //
00291 Surface TemporalTileIntraClear::process(Surface &temporal_tile_map, const Surface &temporal_signal_syms,
00292                                         unsigned transform_block_size) {
00293     // transforms_per_tile is 8 for (4x4) and 16 for (2x2)
00294     const unsigned transforms_per_tile = 32 / transform_block_size;
00295     // when tile map is empty, create a default one
00296     if (temporal_tile_map.empty()) {
00297         temporal_tile_map =
00298             Surface::build_from<uint8_t>()
00299                 .generate(temporal_signal_syms.width() / transforms_per_tile, temporal_signal_syms.height() / transforms_per_tile,
00300                           [&](unsigned x, unsigned y) -> uint8_t { return TemporalType::TEMPORAL_INTR; })
00301                 .finish();
00302     }
00303     const auto src_tile_map = temporal_tile_map.view_as<uint8_t>();
00304     const auto src_syms = temporal_signal_syms.view_as<int16_t>();
00305 
00306     return Surface::build_from<int16_t>()
00307         .generate(temporal_signal_syms.width(), temporal_signal_syms.height(),
00308                   [&](unsigned x, unsigned y) -> int16_t {
00309                       const unsigned tile_x = x / transforms_per_tile;
00310                       const unsigned tile_y = y / transforms_per_tile;
00311 
00312                       const bool tile_intra = (src_tile_map.read(tile_x, tile_y) == TemporalType::TEMPORAL_INTR);
00313                       const bool tile_start = ((x % transforms_per_tile) == 0) && ((y % transforms_per_tile) == 0);
00314 
00315                       if (tile_start || !tile_intra) {
00316                           return src_syms.read(x, y);
00317                       }
00318 
00319                       return 0;
00320                   })
00321         .finish();
00322 }
00323 
00324 // For each block in map - zero prediction if corresponding block is set to INTRA in map
00325 //
00326 Surface ApplyTemporalMap::process(const Surface &src_plane, Surface &map_plane, unsigned transform_block_size) {
00327 
00328     // Scale the residual map to cover source image
00329     //
00330     const unsigned block_w = tile_size(map_plane.width(), src_plane.width());
00331     const unsigned block_h = tile_size(map_plane.height(), src_plane.height());
00332     const unsigned shift_bw = log2(block_w);
00333     const unsigned shift_bh = log2(block_h);
00334 
00335     CHECK(src_plane.width() == map_plane.width() * block_w);
00336     CHECK(src_plane.height() == map_plane.height() * block_h);
00337 
00338     const auto src = src_plane.view_as<int16_t>();
00339     const auto map = map_plane.view_as<uint8_t>();
00340 
00341 #if defined __OPT_MATRIX__
00342     auto dest = Surface::build_from<int16_t>();
00343     dest.reserve(src.width(), src.height());
00344     for (unsigned y = 0; y < src.height(); ++y) {
00345         const int16_t *__restrict psrc = src.data(0, y);
00346         int16_t *__restrict pdst = dest.data(0, y);
00347         for (unsigned x = 0; x < src.width(); ++x) {
00348             // apply the "buffer refresh" per block
00349             if (map.read(x >> shift_bw, y >> shift_bh) == TemporalType::TEMPORAL_INTR)
00350                 // dest.write(x, y, 0);
00351                 *pdst++ = 0;
00352             else
00353                 // dest.write(x, y, src.read(x, y));
00354                 *pdst++ = *psrc;
00355             psrc++;
00356         }
00357     }
00358     return dest.finish();
00359 #else
00360     return Surface::build_from<int16_t>()
00361         .generate(src.width(), src.height(),
00362                   [&](unsigned x, unsigned y) -> int16_t {
00363                       // apply the "buffer refresh" per block
00364                       if (map.read(x >> shift_bw, y >> shift_bh) == TemporalType::TEMPORAL_INTR)
00365                           return 0;
00366                       else
00367                           return src.read(x, y);
00368                   })
00369         .finish();
00370 #endif
00371 }
