00373 // Filter out the embedded user_data
00374 //
00375 Surface UserDataClear::process(const Surface &symbols, UserDataMode user_data) {
00376     unsigned size;
00377     switch (user_data) {
00378     case lctm::UserData_2bits:
00379         size = 2;
00380         break;
00381     case lctm::UserData_6bits:
00382         size = 6;
00383         break;
00384     default:
00385         CHECK(0);
00386         break;
00387     }
00388     const auto src_symbols = symbols.view_as<int16_t>();
00389 
00390 #if defined __OPT_MATRIX__
00391     auto dest = Surface::build_from<int16_t>();
00392     dest.reserve(src_symbols.width(), src_symbols.height());
00393     for (unsigned y = 0; y < src_symbols.height(); ++y) {
00394         const int16_t *__restrict psrc = src_symbols.data(0, y);
00395         int16_t *__restrict pdst = dest.data(0, y);
00396         for (unsigned x = 0; x < src_symbols.width(); ++x) {
00397             uint16_t value = *psrc++;
00398             value >>= size;
00399             bool sign = (value & 0x01) == 0x00 ? false : true;
00400             value >>= 1;
00401             *pdst++ = (int16_t)(sign ? (-value) : (value));
00402         }
00403     }
00404     return dest.finish();
00405 #else
00406     return Surface::build_from<int16_t>()
00407         .generate(src_symbols.width(), src_symbols.height(),
00408                   [&](unsigned x, unsigned y) -> int16_t {
00409                       uint16_t value = src_symbols.read(x, y);
00410                       value >>= size;
00411                       bool sign = (value & 0x01) == 0x00 ? false : true;
00412                       value >>= 1;
00413                       return (int16_t)(sign ? (-value) : (value));
00414                   })
00415         .finish();
00416 #endif
00417 }
